import hashlib,json
from pathlib import Path
import numpy as np
p=Path(__file__).resolve().parent;l=p/'local_recovery';r=l/'gp_transport_calibration01';s=json.loads((r/'SUMMARY.json').read_text());assert s['completed'];costs=[]
for fold in range(4):
    f=l/f'gp_fresh_comparison01/low_rank-{946200001+2*fold}/SUMMARY.json';row=json.loads(f.read_text());assert row['passed'];costs.append(dict(fold=fold,pilot_gradient_calls=row['calls']['gradient'],pilot_post_import_sampling_seconds=row['post_import_sampling_seconds'],receipt=str(f),sha256=hashlib.sha256(f.read_bytes()).hexdigest()))
ledger=dict(pilots=costs,pilot_cost_scope='Full archived training fits, including unused retained draws; do not charge only the400 positions used. Same maps available to both engines.',fit_target_calls=0,fit_wall_time='Not measured in original map fitting; do not assume zero runtime.',calibration_gradient_calls={engine:sum(x.get('calls',{}).get('gradient',0) for x in s['rows'] if x['mode'].startswith('walnuts')==(engine=='walnuts')) for engine in ['walnuts','native']},timing_scope='Concurrent calibration clocks are not comparative runtime evidence.',aws_read_only_check='CLI session expired; current instance state unverified. No restart or budget override performed.')
(r/'COST-LEDGER.json').write_text(json.dumps(ledger,indent=2)+'\n')
lines=['# Full-chain transport calibration','','All four maps and both transformations were retained. Settings were selected only from configurations passing all original-space accuracy and tail gates on every fold. This is calibration, not independent validation.','','| Transform | Engine/mode | Target acceptance | Qualified folds | Geometric calls/minimum bulk ESS |','|---|---|---|---|---|']
for transform in ['affine','quadratic']:
    for mode in ['walnuts_diag','walnuts_dense','diag','low_rank']:
        for accept in [.9,.99]:
            rows=[x for x in s['rows'] if x['transform']==transform and x['mode']==mode and x['target_accept']==accept];assert len(rows)==4;v=float(np.exp(np.mean(np.log([x['calls_per_min_bulk_ess'] for x in rows])))) if all('calls_per_min_bulk_ess' in x for x in rows) else None;lines.append(f"| {transform} | {mode} | {accept} | {sum(x['passed'] for x in rows)}/4 | {v} |")
lines+=['','Selections:','']+[json.dumps(x) for x in s['selected']]+['','The table includes unqualified configurations for diagnosis; their efficiencies are not competitive evidence. No native failure may be labeled inherent superiority without attempting a stronger baseline. In particular a missing transformed-native selection requires a separately preserved repair study before any competitive ratio. Original raw native and the successful conditional-importance control remain relevant.','','COST-LEDGER.json records full pilot cost for every map and all completed calibration calls. Both transformed engines share the same map/pilot expense. Fitting invokes no target evaluations, but its original elapsed time was not measured. Concurrent calibration clocks do not establish wall-time advantage. No production change, application success, uniqueness or goal completion.']
(p/'GP-TRANSPORT-CALIBRATION-RESULT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(dict(selected=s['selected'],ledger=ledger)))
